package com.mavric.health.workflows.application;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import tools.jackson.databind.ObjectMapper;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.identity.*;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.shared.*;
import com.mavric.health.workflows.domain.Requests.*;
import com.mavric.health.persistence.sqlserver.*;
import com.mavric.health.persistence.sqlserver.SqlServerWorkflowStoreTest.Fixture;
import static com.mavric.health.persistence.sqlserver.SqlServerWorkflowStoreTest.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Synthetic service/store integration. No SQL, HTTP or real workflow permissions. */
class WorkflowServiceSqlServerTest {
 final Fixture f=new Fixture();final Sql sql=mock(Sql.class);final Access access=mock(Access.class);final ObjectMapper mapper=new ObjectMapper();final WorkflowService service=new WorkflowService(f.store,sql,access,mapper);
 void actor(String role){f.actor(role);when(access.actor()).thenReturn(f.actor);TraceContext.REQUEST.set(f.request);}
 @BeforeEach void setup(){actor("REC");}
 @AfterEach void clean(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 @Test void twoReadOperationsUseOnlyTheirSpAndNoLocalCatalogPermissions(){f.definitions.add(definition());f.items.add(item());assertEquals(8,((List<Map<String,Object>>)service.definitions()).getFirst().size());assertEquals(12,((List<Map<String,Object>>)service.list("FOLLOW_UP")).getFirst().size());assertEquals(List.of(SqlServerProcedure.WORKFLOW_DEFINITIONS,SqlServerProcedure.WORKFLOW_LIST),f.calls);verify(access,times(2)).actor();verifyNoMoreInteractions(access);verifyNoInteractions(sql);}
 @Test void dynamicRolesDoNotNeedFixedReadRolesOrLocalModuleStatusGuards(){for(String role:List.of("ADM","PRO","REC","ALM","FAR","CAJ","DIA","AUD","PAC","RES")){actor(role);f.request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","SUSPENDED",List.of()));assertEquals(List.of(),service.definitions());assertEquals(List.of(),service.list("FOLLOW_UP"));}verify(access,never()).roles(any(String[].class));verify(access,never()).module(anyString());verify(access,never()).branch(anyString());verifyNoInteractions(sql);}
 @Test void missingRequestAnonymousPlatformAndDiscordantHostDeniedBeforeQueries(){TraceContext.REQUEST.remove();assertEquals(500,assertThrows(ApiException.class,service::definitions).status);verifyNoInteractions(access);actor("REC");when(access.actor()).thenThrow(new ApiException(401,"UNAUTHENTICATED","Safe"));assertEquals(401,assertThrows(ApiException.class,()->service.list("FOLLOW_UP")).status);reset(access);for(String role:List.of("SAD","SOP")){actor(role);assertEquals(403,assertThrows(ApiException.class,service::definitions).status);}actor("REC");f.request.setAttribute("health.tenant","forged");assertEquals(500,assertThrows(ApiException.class,service::definitions).status);actor("REC");f.request.setAttribute("health.actor",new Actor(ACTOR,"Different","synthetic@example.test",TENANT,List.of("REC"),"a".repeat(64)));assertEquals(403,assertThrows(ApiException.class,service::definitions).status);actor("REC");f.request.setAttribute("health.tenant",new TenantRef(OTHER,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of("CORE")));assertEquals(403,assertThrows(ApiException.class,()->service.list("FOLLOW_UP")).status);actor("REC");f.request.removeAttribute("health.tenant");assertEquals(403,assertThrows(ApiException.class,service::definitions).status);verifyNoInteractions(f.executor,sql);}
 @Test void invalidTypeAndSpPermissionErrorsNeverReachLegacy(){assertEquals(400,assertThrows(ApiException.class,()->service.list(null)).status);verifyNoInteractions(f.executor,sql);doThrow(new RuntimeException(new java.sql.SQLException("private-canary",null,51001))).when(f.executor).execute(any(),any(),any(Object[].class));var e=assertThrows(ApiException.class,()->service.list("FOLLOW_UP"));assertEquals(403,e.status);assertNull(e.getCause());assertFalse(e.toString().contains("private-canary"));verify(f.executor,times(1)).execute(eq(SqlServerProcedure.WORKFLOW_LIST),any(),eq("FOLLOW_UP"));verifyNoInteractions(sql);}
 @Test void callerActorTenantRequestAndSecurityAreNotMutatedAndHeadersGiveNoAuthority(){var actor=f.actor;var tenant=f.request.getAttribute("health.tenant");f.request.addHeader("X-Tenant-Id",OTHER);f.request.addHeader("X-Roles","SAD");service.definitions();service.list("FOLLOW_UP");assertSame(actor,f.request.getAttribute("health.actor"));assertSame(tenant,f.request.getAttribute("health.tenant"));assertSame(f.request,TraceContext.REQUEST.get());assertNull(SecurityContextHolder.getContext().getAuthentication());assertEquals(TENANT,f.contexts.getFirst().tenantId());}
 @Test void requiredMappingCommitAndOuterCancellationPropagateSafeErrors(){f.items.add(new LinkedHashMap<>());assertEquals(500,assertThrows(ApiException.class,()->service.list("FOLLOW_UP")).status);assertEquals("rollback",f.manager.events.getLast());f.manager.failCommit=true;assertEquals(500,assertThrows(ApiException.class,service::definitions).status);assertThrows(RuntimeException.class,()->f.manager.outer(()->{service.definitions();throw new RuntimeException("cancel");}));assertEquals("rollback",f.manager.events.getLast());verifyNoInteractions(sql);}
 @Test void minimalSpringChoosesLegacyConstructorWithoutStoreDatasourceOrScheduler(){when(sql.rows(anyString(),any(Object[].class))).thenReturn(List.of());when(access.tenant()).thenReturn(new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of("CORE")));when(sql.one(anyString(),any(Object[].class))).thenReturn(definition());when(sql.strings(any())).thenReturn(List.of("REC"));try(var context=new AnnotationConfigApplicationContext()){context.registerBean(Sql.class,()->sql);context.registerBean(Access.class,()->access);context.registerBean(ObjectMapper.class,()->mapper);context.registerBean(WorkflowService.class);context.refresh();var legacy=context.getBean(WorkflowService.class);assertEquals(List.of(),legacy.definitions());assertEquals(List.of(),legacy.list("FOLLOW_UP"));assertEquals(0,context.getBeanNamesForType(SqlServerWorkflowStore.class).length);assertEquals(0,context.getBeanNamesForType(javax.sql.DataSource.class).length);}verifyNoInteractions(f.executor);verify(sql).one("SELECT * FROM workflow_definitions WHERE type=?","FOLLOW_UP");verify(access).module("CORE");}
 @Test void getCreateStepAndPrivateDefinitionStayLegacyInBothConstructors(){when(access.tenantId()).thenReturn(TENANT);when(access.userId()).thenReturn(ACTOR);when(sql.one(anyString(),any(Object[].class))).thenAnswer(inv->((String)inv.getArgument(0)).contains("workflow_definitions")?definition():new LinkedHashMap<>(item()));when(sql.rows(anyString(),any(Object[].class))).thenReturn(List.of());when(sql.strings(any())).thenAnswer(inv->((List<?>)inv.getArgument(0)).stream().map(Object::toString).toList());when(sql.json(any())).thenAnswer(inv->mapper.writeValueAsString(inv.getArgument(0)));for(var selected:List.of(new WorkflowService(sql,access,mapper),service)){assertTrue(selected.get(ID).containsKey("history"));assertNotNull(selected.create(new Create("FOLLOW_UP",OTHER,null,"Synthetic",Map.of())));assertNotNull(selected.step(ID,new Step(1,"SUBMITTED",Map.of())));}verify(sql,times(2)).call(eq("sp_workflow_create"),any(Object[].class));verify(sql,times(2)).call(eq("sp_workflow_step"),any(Object[].class));verify(access,times(4)).branch(OTHER);verifyNoInteractions(f.executor);}
}
